Set-Location "C:\Users\walim\RedSight"

$ErrorActionPreference = "Stop"

$Root         = "C:\Users\walim\RedSight"
$UiPython     = Join-Path $Root ".venv-ui\Scripts\python.exe"
$ActionPython = Join-Path $Root ".venv-actions\Scripts\python.exe"
$Launcher     = Join-Path $Root "launch_redsight_command_center.py"

$Stage102Ui   = Join-Path $Root "app\ui\action_palette_stage102.py"
$Stage103Ui   = Join-Path $Root "app\ui\action_palette_stage103.py"
$Gateway10    = Join-Path $Root "redsight_actions\gateway_stage10.py"

$Stamp        = Get-Date -Format "yyyyMMdd-HHmmss"
$Runtime      = Join-Path $Root ".repair-backups\stage103-runtime-$Stamp"

New-Item -ItemType Directory -Path $Runtime -Force | Out-Null

$GatewayOut = Join-Path $Runtime "gateway.stdout.log"
$GatewayErr = Join-Path $Runtime "gateway.stderr.log"
$UiOut      = Join-Path $Runtime "command-center.stdout.log"
$UiErr      = Join-Path $Runtime "command-center.stderr.log"

function Invoke-NativeChecked {
    param(
        [Parameter(Mandatory=$true)][string]$Exe,
        [Parameter(Mandatory=$true)][string[]]$Arguments,
        [Parameter(Mandatory=$true)][string]$Label
    )

    Write-Host ">> $Exe $($Arguments -join ' ')"

    $Old = $ErrorActionPreference
    $ErrorActionPreference = "Continue"

    & $Exe @Arguments

    $Code = $LASTEXITCODE

    $ErrorActionPreference = $Old

    if ($Code -ne 0) {
        throw "$Label failed with exit code $Code."
    }
}

function Test-Http200 {
    param(
        [Parameter(Mandatory=$true)][string]$Url,
        [int]$TimeoutSeconds = 4
    )

    $Old = $ErrorActionPreference
    $ErrorActionPreference = "Continue"

    $Code = curl.exe `
        -s `
        -o NUL `
        -w "%{http_code}" `
        --max-time $TimeoutSeconds `
        $Url `
        2>$null

    $Exit = $LASTEXITCODE

    $ErrorActionPreference = $Old

    if ($Exit -ne 0) {
        return $false
    }

    return (($Code | Out-String).Trim() -eq "200")
}

function Wait-Http200 {
    param(
        [Parameter(Mandatory=$true)][string]$Url,
        [int]$Attempts = 60,
        [int]$DelayMilliseconds = 1000
    )

    for ($i = 1; $i -le $Attempts; $i++) {
        if (Test-Http200 -Url $Url -TimeoutSeconds 4) {
            return $true
        }

        Write-Host "Waiting for $Url ... $i/$Attempts"
        Start-Sleep -Milliseconds $DelayMilliseconds
    }

    return $false
}

function Write-Base64Utf8 {
    param(
        [Parameter(Mandatory=$true)][string]$Path,
        [Parameter(Mandatory=$true)][string]$Data
    )

    $Bytes = [Convert]::FromBase64String($Data)
    [System.IO.File]::WriteAllBytes($Path, $Bytes)
}

Write-Host ""
Write-Host "======================================================================"
Write-Host " REDSIGHT STAGE 10.3"
Write-Host " INLINE RED/BLUE CHAT + FILE CONTEXT UPLOAD + FULL RESTART"
Write-Host "======================================================================"
Write-Host ""

foreach ($Required in @(
    $UiPython,
    $ActionPython,
    $Launcher,
    $Stage102Ui,
    $Gateway10
)) {
    if (-not (Test-Path $Required)) {
        throw "Missing required RedSight component: $Required"
    }

    Write-Host "PASS  $Required"
}

