$ErrorActionPreference = "Continue"

& $UiPython -c "import PySide6,httpx,fitz,docx,openpyxl,pptx; print('FILE_CONTEXT_DEPS=PASS')"

$DependencyExit = $LASTEXITCODE
$ErrorActionPreference = $Old

if ($DependencyExit -ne 0) {
    Write-Host "Installing/repairing RedSight chat attachment dependencies..."

    Invoke-NativeChecked `
        -Exe $UiPython `
        -Arguments @(
            "-m","pip","install","--upgrade",
            "PyMuPDF>=1.24,<2",
            "python-docx>=1.1,<2",
            "openpyxl>=3.1,<4",
            "python-pptx>=1.0,<2"
        ) `
        -Label "RedSight file-context dependency installation"

    Invoke-NativeChecked `
        -Exe $UiPython `
        -Arguments @(
            "-c",
            "import fitz,docx,openpyxl,pptx; print('FILE_CONTEXT_DEPS=PASS')"
        ) `
        -Label "RedSight file-context dependency revalidation"
}

Write-Host "FILE_CONTEXT_DEPENDENCIES=PASS"

# ======================================================================
# WRITE SOURCE-AWARE STAGE 10.3 INSTALLER
# ======================================================================

Write-Host ""
Write-Host "=== Installing Stage 10.3 source ==="

$InstallerPy = Join-Path $Runtime "install-stage103.py"

Write-Base64Utf8 `
    -Path $InstallerPy `
    -Data ""

Invoke-NativeChecked `
    -Exe $UiPython `
    -Arguments @($InstallerPy) `
    -Label "Stage 10.3 source installation"

# ======================================================================
# STATIC COMPILE / FILE EXTRACTION VALIDATION
# ======================================================================

Write-Host ""
Write-Host "=== Python compilation ==="

foreach ($Path in @(
    $Stage103Ui,
    $Launcher
)) {
    Invoke-NativeChecked `
        -Exe $UiPython `
        -Arguments @("-m","py_compile",$Path) `
        -Label "Compile $Path"
}

$ValidationPy = Join-Path $Runtime "validate-stage103-static.py"

Write-Base64Utf8 `
    -Path $ValidationPy `
    -Data ""

Invoke-NativeChecked `
    -Exe $UiPython `
    -Arguments @($ValidationPy) `
    -Label "Stage 10.3 static/file-context validation"

# ======================================================================
# DOCKER ENGINE
# ======================================================================

Write-Host ""
Write-Host "=== Docker Desktop ==="

$Old = $ErrorActionPreference
$ErrorActionPreference = "Continue"

docker info 1>$null 2>$null
$DockerOK = ($LASTEXITCODE -eq 0)

$ErrorActionPreference = $Old

if (-not $DockerOK) {
    Write-Host "Docker engine is offline. Starting Docker Desktop..."

    $DockerDesktop = Join-Path $env:ProgramFiles "Docker\Docker\Docker Desktop.exe"

    if (Test-Path $DockerDesktop) {
        Start-Process $DockerDesktop | Out-Null
    }
    else {
        $Old = $ErrorActionPreference
        $ErrorActionPreference = "Continue"
        docker desktop start --detach 1>$null 2>$null
        $ErrorActionPreference = $Old
    }

    for ($i = 1; $i -le 90; $i++) {
        $Old = $ErrorActionPreference
        $ErrorActionPreference = "Continue"

        docker info 1>$null 2>$null
        $DockerOK = ($LASTEXITCODE -eq 0)

        $ErrorActionPreference = $Old

        if ($DockerOK) {
            break
        }

        Write-Host "Waiting for Docker... $i/90"
        Start-Sleep -Seconds 2
    }
}

if (-not $DockerOK) {
    throw "Docker Desktop Linux engine did not become available."
}

Write-Host "DOCKER=ONLINE"

# ======================================================================
# QDRANT + REDSIGHT BACKEND RESTART
# ======================================================================

Write-Host ""
Write-Host "=== Restarting RedSight backend safely ==="

Invoke-NativeChecked `
    -Exe "docker" `
    -Arguments @("compose","up","-d","qdrant") `
    -Label "Qdrant start/verify"

$Old = $ErrorActionPreference
$ErrorActionPreference = "Continue"

docker compose restart redsight

$RestartCode = $LASTEXITCODE
$ErrorActionPreference = $Old

if ($RestartCode -ne 0) {
    Invoke-NativeChecked `
        -Exe "docker" `
        -Arguments @("compose","up","-d","redsight") `
        -Label "RedSight backend start"
}

if (-not (Wait-Http200 `
    -Url "http://127.0.0.1:8000/api/v1/health" `
    -Attempts 75 `
    -DelayMilliseconds 1500
)) {
    Write-Host ""
    Write-Host "=== REDSIGHT BACKEND LOG ==="

    $Old = $ErrorActionPreference
    $ErrorActionPreference = "Continue"

    docker logs --tail 250 redsight

    $ErrorActionPreference = $Old

    throw "RedSight backend failed health validation."
}

Write-Host "REDSIGHT_BACKEND=HEALTHY"

$Old = $ErrorActionPreference
$ErrorActionPreference = "Continue"

docker exec redsight-qdrant curl -fsS http://localhost:6333/readyz

$QdrantExit = $LASTEXITCODE
$ErrorActionPreference = $Old

if ($QdrantExit -ne 0) {
    throw "Qdrant failed readiness validation."
}

Write-Host ""
Write-Host "QDRANT=HEALTHY"

# ======================================================================
# RESTART STAGE 10 ACTION / MEMORY GATEWAY
# ======================================================================

Write-Host ""
Write-Host "=== Restarting Stage 10 Action / Memory Gateway ==="

Get-CimInstance Win32_Process |
    Where-Object {
        $_.Name -match '^python(w)?\.exe$' -and
        $_.CommandLine -and
        (
            $_.CommandLine -match 'redsight_actions\.gateway:app' -or
            $_.CommandLine -match 'redsight_actions\.gateway_stage9:app' -or
            $_.CommandLine -match 'redsight_actions\.gateway_stage91:app' -or
            $_.CommandLine -match 'redsight_actions\.gateway_stage10:app'
        )
    } |
    ForEach-Object {
        Write-Host "Stopping stale gateway PID $($_.ProcessId)"

        Stop-Process `
            -Id $_.ProcessId `
            -Force `
            -ErrorAction SilentlyContinue
    }

Start-Sleep -Milliseconds 700

$GatewayProcess = Start-Process `
    -FilePath $ActionPython `
    -ArgumentList @(
        "-m",
        "uvicorn",
        "redsight_actions.gateway_stage10:app",
        "--host",
        "127.0.0.1",
        "--port",
        "8765",
        "--log-level",
        "warning"
    ) `
    -WorkingDirectory $Root `
    -RedirectStandardOutput $GatewayOut `
    -RedirectStandardError $GatewayErr `
    -PassThru

if (-not (Wait-Http200 `
    -Url "http://127.0.0.1:8765/memory/status" `
    -Attempts 60 `
    -DelayMilliseconds 500
)) {
    Write-Host ""
    Write-Host "=== GATEWAY STDOUT ==="

    if (Test-Path $GatewayOut) {
        Get-Content $GatewayOut -Tail 160
    }

    Write-Host ""
    Write-Host "=== GATEWAY STDERR ==="

    if (Test-Path $GatewayErr) {
        Get-Content $GatewayErr -Tail 250
    }

    throw "Stage 10 Action/Memory Gateway failed to restart."
}

Write-Host "ACTION_MEMORY_GATEWAY=HEALTHY"

# ======================================================================
# DUAL GPU + LM STUDIO CHECKS
# ======================================================================

Write-Host ""
Write-Host "=== GPU / LM Studio validation ==="

$Old = $ErrorActionPreference
$ErrorActionPreference = "Continue"

$Gpu = docker exec redsight nvidia-smi -L
$GpuCode = $LASTEXITCODE

$ErrorActionPreference = $Old

if (
    $GpuCode -ne 0 -or
    ($Gpu | Out-String) -notmatch "GPU 0:" -or
    ($Gpu | Out-String) -notmatch "GPU 1:"
) {
    throw "Dual-GPU validation failed."
}

$Gpu
Write-Host "DUAL_GPU=PASS"

$LmReady = Test-Http200 `
    -Url "http://127.0.0.1:1234/v1/models" `
    -TimeoutSeconds 5

if (-not $LmReady) {
    Write-Warning "LM Studio Local Server is not reachable on port 1234. RedSight UI will still launch, but chat inference requires LM Studio."
}
else {
    Write-Host "LM_STUDIO=CONNECTED"
}

# ======================================================================
# DEEP OFFSCREEN UI TEST
# ======================================================================

Write-Host ""
Write-Host "=== Deep Stage 10.3 inline-chat integration test ==="

$OffscreenPy = Join-Path $Runtime "validate-stage103-offscreen.py"

Write-Base64Utf8 `
    -Path $OffscreenPy `
    -Data ""

Invoke-NativeChecked `
    -Exe $UiPython `
    -Arguments @($OffscreenPy) `
    -Label "Stage 10.3 offscreen UI integration"

# ======================================================================
# ACTUAL REDSIGHT CHAT TRANSPORT TEST WHEN LM STUDIO IS AVAILABLE
# ======================================================================

if ($LmReady) {
    Write-Host ""
    Write-Host "=== RedSight -> LM Studio regression test ==="

    $ChatBody = @{
        messages = @(
            @{
                role = "user"
                content = "Reply with exactly REDSIGHT_STAGE103_READY"
            }
        )
        stream = $false
    } | ConvertTo-Json -Depth 8

    $Chat = Invoke-RestMethod `
        -Uri "http://127.0.0.1:8000/api/v1/chat" `
        -Method Post `
        -ContentType "application/json" `
        -Body $ChatBody `
        -TimeoutSec 240

    if (-not $Chat.message) {
        $Chat | ConvertTo-Json -Depth 10 | Write-Host
        throw "RedSight chat endpoint returned no top-level message."
    }

    Write-Host "CHAT_MESSAGE=$($Chat.message)"
    Write-Host "CHAT_TRANSPORT=PASS"
}

# ======================================================================
# TERMINATE STALE COMMAND CENTER PROCESSES
# ======================================================================

Write-Host ""
Write-Host "=== Terminating stale RedSight UI processes ==="

Get-CimInstance Win32_Process |
    Where-Object {
        $_.Name -match '^python(w)?\.exe$' -and
        $_.CommandLine -and
        (
            $_.CommandLine -match 'launch_redsight_command_center\.py' -or
            $_.CommandLine -match 'app\.ui\.command_center'
        )
    } |
    ForEach-Object {
        Write-Host "Stopping stale UI PID $($_.ProcessId)"

        Stop-Process `
            -Id $_.ProcessId `
            -Force `
            -ErrorAction SilentlyContinue
    }

Start-Sleep -Seconds 1

# ======================================================================
# RELAUNCH REDSIGHT COMMAND CENTER
# ======================================================================

Write-Host ""
Write-Host "======================================================================"
Write-Host " RELAUNCHING REDSIGHT COMMAND CENTER"
Write-Host "======================================================================"
Write-Host ""

$UiProcess = Start-Process `
    -FilePath $UiPython `
    -ArgumentList ('"' + $Launcher + '"') `
    -WorkingDirectory $Root `
    -RedirectStandardOutput $UiOut `
    -RedirectStandardError $UiErr `
    -PassThru

if ($null -eq $UiProcess) {
    throw "Command Center process could not be created."
}

for ($i = 1; $i -le 12; $i++) {
    Start-Sleep -Seconds 1

    $UiProcess.Refresh()

    if ($UiProcess.HasExited) {
        Write-Host ""
        Write-Host "=== COMMAND CENTER STDOUT ==="

        if (Test-Path $UiOut) {
            Get-Content $UiOut -Tail 200
        }

        Write-Host ""
        Write-Host "=== COMMAND CENTER STDERR ==="

        if (Test-Path $UiErr) {
            Get-Content $UiErr -Tail 300
        }

        throw "RedSight Command Center exited during startup."
    }

    Write-Host "UI process alive: $i/12"
}

# ======================================================================
# FINAL VALIDATION
# ======================================================================

if (-not (Test-Http200 `
    -Url "http://127.0.0.1:8000/api/v1/health" `
    -TimeoutSeconds 5
)) {
    throw "Backend failed final health validation."
}

if (-not (Test-Http200 `
    -Url "http://127.0.0.1:8765/memory/status" `
    -TimeoutSeconds 5
)) {
    throw "Action/Memory Gateway failed final health validation."
}

$UiProcess.Refresh()

if ($UiProcess.HasExited) {
    throw "Command Center exited before final validation."
}

